  "content": "import { useState, useEffect } from 'react';
import { customerApi } from '../services/api';

export default function InvoiceFilterPanel({ isOpen, onClose, onApplyFilters }) {
  const [customers, setCustomers] = useState([]);
  const [activeFilters, setActiveFilters] = useState([]);
  const [selectedFilterToAdd, setSelectedFilterToAdd] = useState('');

  const getCurrentMonthString = () => {
    const now = new Date();
    const year = now.getFullYear();
    const month = String(now.getMonth() + 1).padStart(2, '0');
    return `${year}-${month}`;
  };

  const [filters, setFilters] = useState({
    customer: '',
    invoiceMonth: getCurrentMonthString(),
    invoiceMonthOperator: 'On',
    paymentDate: getCurrentMonthString(),
    paymentDateOperator: 'On',
    invoiceAmount: '',
    invoiceAmountOperator: 'Equal To',
    paymentStatus: ''
  });

  const filterDefinitions = [
    { id: 'customer', label: 'Customer' },
    { id: 'invoiceMonth', label: 'Invoice Month' },
    { id: 'paymentDate', label: 'Payment Date' },
    { id: 'invoiceAmount', label: 'Invoice Amount' },
    { id: 'paymentStatus', label: 'Payment Status' }
  ];

  useEffect(() => {
    if (isOpen) {
      loadCustomers();
    }
  }, [isOpen]);

  const loadCustomers = async () => {
    try {
      const customerList = await customerApi.getAll();
      setCustomers(customerList);
    } catch (error) {
      console.error('Error loading customers:', error);
    }
  };

  const handleInputChange = (field, value) => {
    setFilters(prev => ({
      ...prev,
      [field]: value
    }));
  };

  const handleApplyFilters = () => {
    // Transform frontend filters to backend format
    const backendFilters = {};

    // Only include filters that are in activeFilters array
    if (activeFilters.includes('customer') && filters.customer) {
      backendFilters.customer_id = filters.customer;
    }

    if (activeFilters.includes('invoiceMonth') && filters.invoiceMonth) {
      // Convert YYYY-MM to date (first day of month)
      backendFilters.invoice_month_date = filters.invoiceMonth + '-01';
      // Map operator to backend format
      const operatorMap = {
        'On': '==',
        'Before': '<',
        'After': '>'
      };
      backendFilters.invoice_month_operator = operatorMap[filters.invoiceMonthOperator] || '==';
    }

    if (activeFilters.includes('paymentDate') && filters.paymentDate) {
      // Convert YYYY-MM to date (first day of month)
      backendFilters.payment_date = filters.paymentDate + '-01';
      // Map operator to backend format
      const operatorMap = {
        'On': '==',
        'Before': '<',
        'After': '>'
      };
      backendFilters.payment_date_operator = operatorMap[filters.paymentDateOperator] || '==';
    }

    if (activeFilters.includes('invoiceAmount') && filters.invoiceAmount) {
      backendFilters.invoice_amount = parseFloat(filters.invoiceAmount);
      // Map operator to backend format
      const operatorMap = {
        'Greater Than': '>',
        'Less Than': '<',
        'Equal To': '=='
      };
      backendFilters.invoice_amount_operator = operatorMap[filters.invoiceAmountOperator] || '==';
    }

    if (activeFilters.includes('paymentStatus') && filters.paymentStatus) {
      // Map payment status string to boolean flags
      const statusMap = {
        'Paid': { payment_status_is_paid: true },
        'Pending': { payment_status_is_pending: true },
        'Loss': { payment_status_is_loss: true },
        'Not Paid': { payment_status_not_paid: true },
        'Not Pending': { payment_status_not_pending: true },
        'Not Loss': { payment_status_not_loss: true }
      };
      Object.assign(backendFilters, statusMap[filters.paymentStatus] || {});
    }

    onApplyFilters(backendFilters);
    onClose();
  };

  const handleAddFilter = () => {
    if (selectedFilterToAdd && !activeFilters.includes(selectedFilterToAdd)) {
      setActiveFilters(prev => [...prev, selectedFilterToAdd]);
      setSelectedFilterToAdd('');
    }
  };

  const handleRemoveFilter = (filterId) => {
    setActiveFilters(prev => prev.filter(id => id !== filterId));
  };

  const handleClearFilters = () => {
    const clearedFilters = {
      customer: '',
      invoiceMonth: getCurrentMonthString(),
      invoiceMonthOperator: 'On',
      paymentDate: getCurrentMonthString(),
      paymentDateOperator: 'On',
      invoiceAmount: '',
      invoiceAmountOperator: 'Equal To',
      paymentStatus: ''
    };
    setFilters(clearedFilters);
    setActiveFilters([]);
    onApplyFilters({});
  };

  const availableFilters = filterDefinitions.filter(
    filter => !activeFilters.includes(filter.id)
  );

  const renderFilterControl = (filterId) => {
    switch (filterId) {
      case 'customer':
        return (
          <div className="relative mb-4" key={filterId}>
            <div className="flex justify-between items-center mb-2">
              <label className="text-sm font-semibold text-gray-700 dark:text-gray-300">Customer</label>
              <button
                type="button"
                className="text-gray-400 hover:text-red-500 transition-colors"
                onClick={() => handleRemoveFilter(filterId)}
                aria-label="Remove customer filter"
              >
                <span className="material-icons-outlined text-lg">close</span>
              </button>
            </div>
            <select
              value={filters.customer}
              onChange={(e) => handleInputChange('customer', e.target.value)}
              className="w-full px-4 py-3 bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-xl text-gray-900 dark:text-white focus:ring-2 focus:ring-primary focus:border-transparent transition-all"
            >
              <option value="">All Customers</option>
              {customers.map((customer) => (
                <option key={customer.customer_id} value={customer.customer_id}>
                  {customer.name}
                </option>
              ))}
            </select>
          </div>
        );

      case 'invoiceMonth':
        return (
          <div className="relative mb-4" key={filterId}>
            <div className="flex justify-between items-center mb-2">
              <label className="text-sm font-semibold text-gray-700 dark:text-gray-300">Invoice Month</label>
              <button
                type="button"
                className="text-gray-400 hover:text-red-500 transition-colors"
                onClick={() => handleRemoveFilter(filterId)}
                aria-label="Remove invoice month filter"
              >
                <span className="material-icons-outlined text-lg">close</span>
              </button>
            </div>
            <div className="grid grid-cols-2 gap-3">
              <input
                type="month"
                value={filters.invoiceMonth}
                onChange={(e) => handleInputChange('invoiceMonth', e.target.value)}
                className="px-4 py-3 bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-xl text-gray-900 dark:text-white focus:ring-2 focus:ring-primary focus:border-transparent transition-all"
              />
              <select
                value={filters.invoiceMonthOperator}
                onChange={(e) => handleInputChange('invoiceMonthOperator', e.target.value)}
                className="px-4 py-3 bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-xl text-gray-900 dark:text-white focus:ring-2 focus:ring-primary focus:border-transparent transition-all"
              >
                <option value="On">On</option>
                <option value="Before">Before</option>
                <option value="After">After</option>
              </select>
            </div>
          </div>
        );

      case 'paymentDate':
        return (
          <div className="relative mb-4" key={filterId}>
            <div className="flex justify-between items-center mb-2">
              <label className="text-sm font-semibold text-gray-700 dark:text-gray-300">Payment Date</label>
              <button
                type="button"
                className="text-gray-400 hover:text-red-500 transition-colors"
                onClick={() => handleRemoveFilter(filterId)}
                aria-label="Remove payment date filter"
              >
                <span className="material-icons-outlined text-lg">close</span>
              </button>
            </div>
            <div className="grid grid-cols-2 gap-3">
              <input
                type="month"
                value={filters.paymentDate}
                onChange={(e) => handleInputChange('paymentDate', e.target.value)}
                className="px-4 py-3 bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-xl text-gray-900 dark:text-white focus:ring-2 focus:ring-primary focus:border-transparent transition-all"
              />
              <select
                value={filters.paymentDateOperator}
                onChange={(e) => handleInputChange('paymentDateOperator', e.target.value)}
                className="px-4 py-3 bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-xl text-gray-900 dark:text-white focus:ring-2 focus:ring-primary focus:border-transparent transition-all"
              >
                <option value="On">On</option>
                <option value="Before">Before</option>
                <option value="After">After</option>
              </select>
            </div>
          </div>
        );

      case 'invoiceAmount':
        return (
          <div className="relative mb-4" key={filterId}>
            <div className="flex justify-between items-center mb-2">
              <label className="text-sm font-semibold text-gray-700 dark:text-gray-300">Invoice Amount</label>
              <button
                type="button"
                className="text-gray-400 hover:text-red-500 transition-colors"
                onClick={() => handleRemoveFilter(filterId)}
                aria-label="Remove invoice amount filter"
              >
                <span className="material-icons-outlined text-lg">close</span>
              </button>
            </div>
            <div className="grid grid-cols-2 gap-3">
              <input
                type="number"
                step="0.01"
                min="0"
                value={filters.invoiceAmount}
                onChange={(e) => handleInputChange('invoiceAmount', e.target.value)}
                placeholder="0.00"
                className="px-4 py-3 bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-xl text-gray-900 dark:text-white focus:ring-2 focus:ring-primary focus:border-transparent transition-all"
              />
              <select
                value={filters.invoiceAmountOperator}
                onChange={(e) => handleInputChange('invoiceAmountOperator', e.target.value)}
                className="px-4 py-3 bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-xl text-gray-900 dark:text-white focus:ring-2 focus:ring-primary focus:border-transparent transition-all"
              >
                <option value="Greater Than">Greater Than</option>
                <option value="Less Than">Less Than</option>
                <option value="Equal To">Equal To</option>
              </select>
            </div>
          </div>
        );

      case 'paymentStatus':
        return (
          <div className="relative mb-4" key={filterId}>
            <div className="flex justify-between items-center mb-2">
              <label className="text-sm font-semibold text-gray-700 dark:text-gray-300">Payment Status</label>
              <button
                type="button"
                className="text-gray-400 hover:text-red-500 transition-colors"
                onClick={() => handleRemoveFilter(filterId)}
                aria-label="Remove payment status filter"
              >
                <span className="material-icons-outlined text-lg">close</span>
              </button>
            </div>
            <select
              value={filters.paymentStatus}
              onChange={(e) => handleInputChange('paymentStatus', e.target.value)}
              className="w-full px-4 py-3 bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-xl text-gray-900 dark:text-white focus:ring-2 focus:ring-primary focus:border-transparent transition-all"
            >
              <option value="">All Statuses</option>
              <option value="Paid">Paid</option>
              <option value="Pending">Pending</option>
              <option value="Loss">Loss</option>
              <option value="Not Paid">Not Paid</option>
              <option value="Not Pending">Not Pending</option>
              <option value="Not Loss">Not Loss</option>
            </select>
          </div>
        );

      default:
        return null;
    }
  };

  if (!isOpen) {
    return null;
  }

  return (
    <>
      {/* Overlay */}
      <div
        className="fixed inset-0 bg-black/50 backdrop-blur-sm flex items-center justify-center z-50 p-4"
        onClick={onClose}
      />

      {/* Panel Content - Slide in from right */}
      <div className="fixed right-0 top-0 h-full w-full max-w-md bg-white dark:bg-card-dark shadow-2xl z-50 transform transition-transform duration-300 ease-in-out overflow-y-auto">
        <div className="flex flex-col h-full">
          {/* Header */}
          <div className="flex justify-between items-center p-6 border-b border-gray-100 dark:border-gray-700 shrink-0">
            <div className="flex items-center gap-3">
              <div className="p-2 bg-primary/10 rounded-xl">
                <span className="material-icons-outlined text-primary">filter_list</span>
              </div>
              <h2 className="text-2xl font-bold text-gray-900 dark:text-white">Filter Invoices</h2>
            </div>
            <button
              onClick={onClose}
              className="p-2 hover:bg-gray-100 dark:hover:bg-gray-800 rounded-xl transition-colors"
              aria-label="Close filter panel"
            >
              <span className="material-icons-outlined text-gray-600 dark:text-gray-400">close</span>
            </button>
          </div>

          {/* Body */}
          <div className="flex-1 overflow-y-auto p-6">
            <form onSubmit={(e) => e.preventDefault()}>
              {/* Filter Addition Controls */}
              {availableFilters.length > 0 && (
                <div className="mb-6">
                  <label className="text-sm font-semibold text-gray-700 dark:text-gray-300 mb-2 block">
                    Add Filter
                  </label>
                  <div className="flex gap-2">
                    <select
                      value={selectedFilterToAdd}
                      onChange={(e) => setSelectedFilterToAdd(e.target.value)}
                      className="flex-1 px-4 py-3 bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-xl text-gray-900 dark:text-white focus:ring-2 focus:ring-primary focus:border-transparent transition-all"
                    >
                      <option value="">Select a filter...</option>
                      {availableFilters.map(filter => (
                        <option key={filter.id} value={filter.id}>
                          {filter.label}
                        </option>
                      ))}
                    </select>
                    <button
                      type="button"
                      onClick={handleAddFilter}
                      disabled={!selectedFilterToAdd}
                      className="px-4 py-3 bg-primary hover:bg-sky-600 disabled:bg-gray-300 dark:disabled:bg-gray-700 text-white font-medium rounded-xl transition-all flex items-center gap-2 disabled:cursor-not-allowed"
                    >
                      <span className="material-icons-outlined">add</span>
                    </button>
                  </div>
                </div>
              )}

              {/* Active Filters */}
              <div className="space-y-4">
                {activeFilters.length > 0 && (
                  <div className="mb-4">
                    <h3 className="text-sm font-semibold text-gray-700 dark:text-gray-300 mb-3">
                      Active Filters
                    </h3>
                  </div>
                )}
                {activeFilters.map(filterId => renderFilterControl(filterId))}
              </div>

              {activeFilters.length === 0 && availableFilters.length > 0 && (
                <div className="text-center py-12">
                  <div className="inline-flex items-center justify-center w-16 h-16 rounded-full bg-gray-100 dark:bg-gray-800 mb-4">
                    <span className="material-icons-outlined text-gray-400 text-3xl">filter_alt_off</span>
                  </div>
                  <p className="text-gray-500 dark:text-gray-400">
                    No filters active. Add a filter to get started.
                  </p>
                </div>
              )}
            </form>
          </div>

          {/* Footer - Action Buttons */}
          <div className="p-6 border-t border-gray-100 dark:border-gray-700 shrink-0">
            <div className="flex gap-3">
              <button
                type="button"
                onClick={handleClearFilters}
                className="flex-1 px-5 py-3 bg-gray-100 dark:bg-gray-800 hover:bg-gray-200 dark:hover:bg-gray-700 text-gray-700 dark:text-gray-300 font-medium rounded-xl transition-all"
              >
                Clear All
              </button>
              <button
                type="button"
                onClick={handleApplyFilters}
                className="flex-1 px-5 py-3 bg-primary hover:bg-sky-600 text-white font-medium rounded-xl shadow-md hover:shadow-lg transition-all"
              >
                Apply Filters
              </button>
            </div>
          </div>
        </div>
      </div>
    </>
  );
}
